"""Validate a staged Cycles result and install only this pilot's allowlisted assets.

Never writes to another checkout. Run from the isolated branch after inspecting the bake.
"""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
import struct

ROOT = Path(__file__).resolve().parents[2]


def ts_string(value: str) -> str:
    return "'" + value.replace("\\", "\\\\").replace("'", "\\'") + "'"


def ts_manifest(runtime: dict) -> str:
    emitter = runtime["emitter"]
    lines = [
        "// Generated by tools/bake/install_palace.py. Scene mismatch disables the texture.",
        "export const PALACE_BAKE = {",
        f"  version: {runtime['version']},",
        f"  sceneHash: {ts_string(runtime['sceneHash'])},",
        f"  bounds: {json.dumps(runtime['bounds'])},",
        f"  receiverY: {runtime['receiverY']},",
        f"  file: {ts_string(runtime['file'])},",
        f"  textureHash: {ts_string(runtime['textureHash'])},",
        f"  width: {runtime['width']},",
        f"  height: {runtime['height']},",
        f"  radianceScale: {runtime['radianceScale']:.1f},",
        "  emitter: {",
        f"    label: {ts_string(emitter['label'])},",
        f"    sublabel: {ts_string(emitter['sublabel'])},",
        f"    x: {emitter['x']},",
        f"    y: {emitter['y']},",
        f"    z: {emitter['z']},",
        f"    yaw: {emitter['yaw']},",
        f"    w: {emitter['w']},",
        f"    h: {emitter['h']},",
        f"    color: {emitter['color']},",
        "  },",
        "} as const;",
        "",
    ]
    return "\n".join(lines)


def validate_result(source: Path) -> dict:
    manifest = json.loads((source / "manifest.json").read_text(encoding="utf-8"))
    expected = {"version": 1, "bounds": [48, -22, 80, 22], "receiverY": 0.02,
                "file": "courtyard.png", "radianceScale": 16}
    if any(manifest.get(k) != v for k, v in expected.items()):
        raise ValueError("Result is not the bounded Palace pilot")
    if not isinstance(manifest.get("sceneHash"), str) or not manifest["sceneHash"]:
        raise ValueError("Missing scene fingerprint")
    if not isinstance(manifest.get("emitter"), dict):
        raise ValueError("Missing exact emitter specification")
    data = (source / "courtyard.png").read_bytes()
    if len(data) > 4 * 1024 * 1024 or data[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError("Invalid or oversized pilot image")
    if data[12:16] != b"IHDR":
        raise ValueError("Missing PNG header")
    width, height, depth, kind = struct.unpack(">IIBB", data[16:26])
    if width != height or width not in (256, 512, 1024) or depth != 8 or kind != 6:
        raise ValueError("Expected bounded square RGBA8 image")
    if manifest.get("width") != width or manifest.get("height") != height:
        raise ValueError("Image/manifest dimensions differ")
    return manifest


def install(source: Path) -> None:
    dot_git = ROOT / ".git"
    # An original checkout (.git directory) or a linked worktree (.git file); never a copied directory.
    if not dot_git.exists():
        raise ValueError("Pilot installer requires a git checkout")
    import subprocess

    branch = subprocess.run(
        ["git", "-c", f"safe.directory={ROOT.as_posix()}", "branch", "--show-current"],
        cwd=ROOT, text=True, capture_output=True, check=True,
    ).stdout.strip()
    # Kiran (2026-10-13): installs run on main (the lead bakes there) or the Codex staging branch.
    if branch not in ("main", "codex/isolated-finish"):
        raise ValueError(f"Refusing to install onto branch {branch!r}")
    manifest = validate_result(source)
    manifest["textureHash"] = hashlib.sha256((source / "courtyard.png").read_bytes()).hexdigest()
    target = ROOT / "packages/client/public/lightmaps/palace-pilot"
    target.mkdir(parents=True, exist_ok=True)
    (target / "courtyard.png").write_bytes((source / "courtyard.png").read_bytes())
    (target / "manifest.json").write_text(
        json.dumps(manifest, indent=2) + "\n", encoding="utf-8",
    )
    runtime_keys = ("version", "sceneHash", "bounds", "receiverY", "file", "width", "height",
                    "radianceScale", "emitter", "textureHash")
    runtime = {key: manifest[key] for key in runtime_keys}
    (ROOT / "packages/client/src/render/palaceBakeManifest.ts").write_text(
        ts_manifest(runtime),
        encoding="utf-8",
    )
    print(f"Installed {len((target / 'courtyard.png').read_bytes())} bytes on {branch}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    args = parser.parse_args()
    install(args.source.resolve())
